import { useState, useEffect } from "react";
import { useGamepad, type ControllerAction } from "../hooks/useGamepad";

import "../css/friends.css";

import AddFriendsIcon from "../assets/ui/addfriend.svg?react";
import DeleteIcon from "../assets/ui/delete.svg?react";
import { FriendListType, FriendType } from "../types";

type FriendsProps = {
  onCancel?: () => void;
};

type TapTypes = "Friend List" | "Add Friend" | "Friend Requests";

function Friends({ onCancel }: FriendsProps) {
  const [currentTap, setCurrentTap] = useState<TapTypes>("Friend List");

  //Todo: get friendlist from server

  const UserData: FriendListType = {
    friends:[
      {
      userID: 48932324,
      username: "UniquezHD",
      activity: "Playing: Plants vs. Zombies™: Replanted",
      profilePicture:
        "data:image/png;base64, ",
      onlineStatus: true,
    },
    {
      userID: 4325235,
      username: "Xiiqaz",
      activity: "Playing: The Outlast Trials",
      profilePicture:
        "data:image/png;base64, ",
      onlineStatus: true,
    },
    {
      userID: 4325235,
      username: "Aooosos",
      activity: "Main menu",
      profilePicture:
        "data:image/png;base64,",
      onlineStatus: false,
    },
    ]
  };

  const [friendList, setFriendList] = useState<FriendListType>(UserData);

  useGamepad({
    onAction: (action: ControllerAction) => {
      switch (action) {
        case "circle":
          onCancel?.();
          break;
      }
    },
  });

  const DeleteFriendRequest = () => {};

  const AcceptFriendRequest = () => {};

  const SendFriendRequest = () => {};

  const GetFriendListData = () => {};

  useEffect(() => {
    GetFriendListData();
  }, []);

  return (
    <>
      <div className="friends-overlay">
        <div className="friends-container">
          <div className="friends-top">
            <h3>{currentTap}</h3>
          </div>

          <div className="friends-middle">
            <button
              data-controller-group="friends"
              data-controller-focus
              className="friends-tap"
              onClick={() => {
                setCurrentTap("Friend List");
              }}
            >
              <span>Friend List</span>
            </button>

            <button
              data-controller-group="friends"
              data-controller-focus
              className="friends-tap"
              onClick={() => {
                setCurrentTap("Add Friend");
              }}
            >
              <span>Add Friend</span>
            </button>

            <button
              data-controller-group="friends"
              data-controller-focus
              className="friends-tap"
              onClick={() => {
                setCurrentTap("Friend Requests");
              }}
            >
              <span>Friend Requests</span>
            </button>
          </div>

          {currentTap === "Friend List" && (
            <div className="friends-list">
              {friendList && friendList.friends.length > 0 ? (
                <>
                  {friendList.friends.map((item: FriendType, i: number) => {
                    return (
                      <>
                        <button
                        key={i}
                          className="friends-list-item"
                          data-controller-focus
                          data-controller-group="friends"
                        >
                          <img src={item.profilePicture} />
                          <div
                            className={`friends-online-indicator ${item.onlineStatus ? "online" : "offline"}`}
                          />
                          <div className="friends-list-info">
                            <span className="friends-list-info-gamertag">
                              {item.username}
                            </span>
                            <span className="friends-list-info-now-playing">
                              {item.onlineStatus && item.activity}
                            </span>
                          </div>
                        </button>
                      </>
                    );
                  })}
                </>
              ) : (
                <>
                  <p style={{ color: "rgba(255, 255, 255, 0.445)", textAlign: "center" }}>Friend List is empty</p>
                </>
              )}
            </div>
          )}

          {currentTap === "Add Friend" && (
            <>
              <div className="friends-tap-add-friend">
                <button
                  data-controller-group="friends"
                  data-controller-focus
                  className="friends-add-friend"
                >
                  <AddFriendsIcon fill="currentColor" />
                </button>

                <input
                  className="friends-input"
                  placeholder="Enter Username"
                  onClick={() => {}}
                  data-controller-focus
                  data-controller-group="friends"
                />
              </div>

              <div className="friends-list">
                <button
                  className="friends-list-item"
                  data-controller-focus
                  data-controller-group="friends"
                  onClick={() => {
                    SendFriendRequest();
                  }}
                >
                  <img src="data:image/png;base64, " />

                  <div className="friends-list-info">
                    <span className="friends-list-info-gamertag">
                      UniquezHD
                    </span>
                  </div>
                </button>
              </div>
            </>
          )}

          {currentTap === "Friend Requests" && (
            <div className="friends-list">
              <button
                className="friends-list-item"
                data-controller-focus
                data-controller-group="friends"
              >
                <img src="data:image/png;base64, " />

                <div className="friends-request-list-info">
                  <span className="friends-list-info-gamertag">Xiiqaz</span>

                  <div className="friends-request-options">
                    <button
                      data-controller-group="friends"
                      data-controller-focus
                      className="friends-request-options-buttons"
                      onClick={() => {
                        AcceptFriendRequest();
                      }}
                    >
                      <AddFriendsIcon fill="currentColor" />
                    </button>

                    <button
                      data-controller-group="friends"
                      data-controller-focus
                      className="friends-request-options-buttons"
                      onClick={() => {
                        DeleteFriendRequest();
                      }}
                    >
                      <DeleteIcon />
                    </button>
                  </div>
                </div>
              </button>
            </div>
          )}
        </div>
      </div>
    </>
  );
}

export default Friends;
